import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { MapContainer, TileLayer, Polyline, Marker, useMap } from 'react-leaflet';
import L from 'leaflet';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
// import GaugeChart from 'react-gauge-chart'; // This line is removed.

// --- Helper Functions & Constants ---

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// A placeholder icon for the vehicle. Using a simple SVG arrow.
const vehicleIconSvg = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23facc15" width="36px" height="36px">
  <path d="M12 2L2.5 21.5h19L12 2zm0 4.68L17.31 19.5H6.69L12 6.68z"/>
</svg>
`;

const vehicleIcon = new L.DivIcon({
  html: `<div id="vehicle-icon-wrapper" style="transform-origin: center; transition: transform 0.5s linear;"><img src="data:image/svg+xml,${vehicleIconSvg}"/></div>`,
  className: '',
  iconSize: [36, 36],
  iconAnchor: [18, 18],
});


// --- Custom Gauge Component ---
/**
 * A custom SVG gauge component to replace the incompatible react-gauge-chart library.
 */
const CustomGauge = ({ value, min = 0, max = 100, label, colors = ['#ef4444', '#facc15', '#84cc16'], width = 150 }) => {
  const height = width * 0.75;
  const strokeWidth = width * 0.1;
  const radius = (width / 2) - (strokeWidth / 2);
  const cx = width / 2;
  const cy = width / 2;

  const START_ANGLE = -135;
  const END_ANGLE = 135;
  const ANGLE_RANGE = END_ANGLE - START_ANGLE;

  const polarToCartesian = (centerX, centerY, radius, angleInDegrees) => {
    const angleInRadians = (angleInDegrees * Math.PI) / 180.0;
    return {
      x: centerX + radius * Math.cos(angleInRadians),
      y: centerY + radius * Math.sin(angleInRadians),
    };
  };

  const describeArc = (x, y, radius, startAngle, endAngle) => {
    const start = polarToCartesian(x, y, radius, endAngle);
    const end = polarToCartesian(x, y, radius, startAngle);
    const largeArcFlag = endAngle - startAngle <= 180 ? '0' : '1';
    const d = ['M', start.x, start.y, 'A', radius, radius, 0, largeArcFlag, 0, end.x, end.y].join(' ');
    return d;
  };

  const clampedValue = Math.max(min, Math.min(value, max));
  const percent = (clampedValue - min) / (max - min);
  const valueAngle = START_ANGLE + (percent * ANGLE_RANGE);

  const formatTextValue = () => {
      if (value === undefined || value === null) return '';
      // Heuristic to format as integer or one decimal place
      return value % 1 === 0 ? Math.round(value) : value.toFixed(1);
  };

  return (
    <div className="text-center">
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        <defs>
          <linearGradient id={`gauge-gradient-${label.replace(/\s/g, '-')}`} x1="0%" y1="0%" x2="100%" y2="0%">
            {colors.map((color, index) => (
              <stop key={index} offset={`${(index / (colors.length -1)) * 100}%`} stopColor={color} />
            ))}
          </linearGradient>
        </defs>

        {/* Background Arc */}
        <path
          d={describeArc(cx, cy, radius, START_ANGLE, END_ANGLE)}
          fill="none"
          stroke="#404040"
          strokeWidth={strokeWidth}
          strokeLinecap="round"
        />

        {/* Value Arc */}
        <path
          d={describeArc(cx, cy, radius, START_ANGLE, valueAngle)}
          fill="none"
          stroke={`url(#gauge-gradient-${label.replace(/\s/g, '-')})`}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          style={{ transition: 'stroke-dashoffset 0.5s ease-in-out' }}
        />

        {/* Text Value */}
        <text
          x="50%"
          y="50%"
          dy="0.1em"
          textAnchor="middle"
          fill="#FFFFFF"
          fontSize={width * 0.2}
          fontWeight="bold"
          style={{ transition: 'fill 0.5s ease-in-out' }}
        >
          {formatTextValue()}
        </text>
      </svg>
      <span className="text-sm font-semibold">{label}</span>
    </div>
  );
};


// --- React Components ---

/**
 * A component to handle map rotation and view centering.
 * Leaflet doesn't natively support map rotation (bearing).
 * This component applies a CSS transform to the map container to achieve the effect.
 * NOTE: This can cause map labels and controls to appear rotated. It's a trade-off for the "direction of travel is up" feature.
 */
const MapRotator = ({ center, bearing, zoom }) => {
  const map = useMap();

  useEffect(() => {
    const mapContainer = map.getContainer();
    if (mapContainer) {
      // Rotate the entire map container
      mapContainer.style.transformOrigin = 'center';
      mapContainer.style.transition = 'transform 1s linear';
      mapContainer.style.transform = `rotate(${360 - bearing}deg)`;
    }
    map.setView(center, zoom);
  }, [map, center, bearing, zoom]);

  return null;
};

// Main LogPlayback Component
const LogPlayback = () => {
  const { logId } = useParams();
  const navigate = useNavigate();
  const [logData, setLogData] = useState([]);
  const [logIndex, setLogIndex] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Playback state
  const [isPlaying, setIsPlaying] = useState(false);
  const [playbackSpeed, setPlaybackSpeed] = useState(1);
  const [currentIndex, setCurrentIndex] = useState(0);

  // PID selection state
  const [availablePids, setAvailablePids] = useState([]);
  const [selectedPids, setSelectedPids] = useState([]);

  const timerRef = useRef(null);

  // Fetch log data on component mount
  useEffect(() => {
    axios.get(`${API_URL}/api/logs/${logId}/data`)
      .then(response => {
        const data = response.data;
        if (data && data.length > 0) {
          // Clean and process data
          const processedData = data.map(row => {
            const newRow = {};
            for (const key in row) {
              const value = parseFloat(row[key]);
              newRow[key] = isNaN(value) ? row[key] : value;
            }
            return newRow;
          });

          setLogData(processedData);
          setLogIndex(response.data.log_index || {});

          const pids = Object.keys(processedData[0] || {}).filter(p => p !== 'timestamp' && p !== 'GPS Latitude' && p !== 'GPS Longitude' && p !== 'GPS Bearing');
          setAvailablePids(pids);
          // Set default PIDs for the chart
          setSelectedPids(pids.slice(0, 3));
        } else {
          setError('No data available for this log.');
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching log data:", err);
        setError('Failed to fetch log data.');
        setLoading(false);
      });
  }, [logId]);

  // The core playback loop effect
  const runPlayback = useCallback(() => {
    if (!isPlaying || logData.length === 0) {
      return;
    }

    timerRef.current = setTimeout(() => {
      setCurrentIndex(prevIndex => {
        const nextIndex = prevIndex + 1;
        if (nextIndex >= logData.length) {
          setIsPlaying(false);
          return prevIndex;
        }

        // Calculate time to next frame to simulate real-time playback
        const currentTime = logData[prevIndex].timestamp;
        const nextTime = logData[nextIndex].timestamp;
        const delay = (nextTime - currentTime) * 1000;

        // Schedule the next step
        clearTimeout(timerRef.current);
        if (isPlaying) {
           timerRef.current = setTimeout(runPlayback, delay / playbackSpeed);
        }

        return nextIndex;
      });
    }, 0); // Start the loop immediately

  }, [isPlaying, playbackSpeed, logData]);


  useEffect(() => {
    if (isPlaying) {
      runPlayback();
    } else {
      clearTimeout(timerRef.current);
    }
    return () => clearTimeout(timerRef.current);
  }, [isPlaying, runPlayback]);


  // Memoized values to prevent unnecessary recalculations
  const currentDataPoint = useMemo(() => logData[currentIndex] || null, [logData, currentIndex]);

  const gpsTrack = useMemo(() => {
    return logData
      .filter(p => p['GPS Latitude'] && p['GPS Longitude'])
      .map(p => [p['GPS Latitude'], p['GPS Longitude']]);
  }, [logData]);

  // Creates colored line segments based on GPS speed
  const coloredSegments = useMemo(() => {
    if (logData.length < 2) return [];

    const segments = [];
    const minSpeed = 0, maxSpeed = 80; // MPH for color scaling

    const getColor = (speed) => {
      const clampedSpeed = Math.max(minSpeed, Math.min(speed, maxSpeed));
      const ratio = clampedSpeed / (maxSpeed - minSpeed);
      const h = (1 - ratio) * 240; // Blue (slow) to Red (fast)
      return `hsl(${h}, 100%, 50%)`;
    };

    for (let i = 0; i < logData.length - 1; i++) {
        const p1 = logData[i];
        const p2 = logData[i+1];
        if (p1['GPS Latitude'] && p1['GPS Longitude'] && p2['GPS Latitude'] && p2['GPS Longitude']) {
            segments.push({
                positions: [[p1['GPS Latitude'], p1['GPS Longitude']], [p2['GPS Latitude'], p2['GPS Longitude']]],
                color: getColor(p1['GPS Speed (MPH)'] || 0)
            });
        }
    }
    return segments;
  }, [logData]);

  const chartData = useMemo(() => {
      const window = 30; // Show +/- 30 points in chart
      const start = Math.max(0, currentIndex - window);
      const end = Math.min(logData.length, currentIndex + window);
      return logData.slice(start, end);
  }, [logData, currentIndex]);


  // Event Handlers
  const handlePlayPause = () => setIsPlaying(p => !p);
  const handleSpeedChange = (speed) => setPlaybackSpeed(speed);
  const handleScrub = (e) => {
    const newIndex = parseInt(e.target.value, 10);
    setCurrentIndex(newIndex);
    if(isPlaying) {
      setIsPlaying(false); // Pause on manual scrub
    }
  };
  const handlePidChange = (index, pid) => {
    setSelectedPids(pids => {
        const newPids = [...pids];
        newPids[index] = pid;
        return newPids;
    });
  };

  // --- Render Logic ---

  if (loading) {
    return <div className="text-white text-center p-8">Loading Log Data...</div>;
  }
  if (error) {
    return <div className="text-red-500 text-center p-8">{error}</div>;
  }
  if (!currentDataPoint) {
    return <div className="text-white text-center p-8">No data points to display.</div>;
  }

  const currentPosition = [currentDataPoint['GPS Latitude'], currentDataPoint['GPS Longitude']];
  const currentBearing = currentDataPoint['GPS Bearing'] || 0;

  // PID values for gauges
  const rpm = currentDataPoint['Engine RPM (RPM)'] || 0;
  const volts = currentDataPoint['Control Module Power Supply (V)'] || 0;
  const mpg = currentDataPoint['Instant fuel economy (MPG)'] || 0;

  return (
    <>
      <style>{`
        .leaflet-container { 
          background: #333;
          width: 100vw;
          height: 100vh;
        }
        .gauge-container .gauge-chart .color-arc, .gauge-container .gauge-chart .value-text {
          transition: all 0.5s ease-in-out;
        }
      `}</style>

      <div className="absolute inset-0 bg-gray-900 text-gray-200 font-sans">
        {gpsTrack.length > 0 && (
          <MapContainer center={currentPosition} zoom={18} scrollWheelZoom={true} className="h-full w-full">
            <TileLayer
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
              url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
            />

            {coloredSegments.map((segment, i) => (
                <Polyline key={i} positions={segment.positions} color={segment.color} weight={5} opacity={0.7} />
            ))}

            <Marker position={currentPosition} icon={vehicleIcon} />
            <MapRotator center={currentPosition} bearing={currentBearing} zoom={18} />
          </MapContainer>
        )}

        {/* --- UI Overlays --- */}

        {/* Top Bar */}
        <div className="absolute top-0 left-0 right-0 p-3 bg-black bg-opacity-50 flex items-center justify-between z-[1000] backdrop-blur-sm">
          <div className="flex items-center">
            <button onClick={() => navigate('/')} className="mr-4 text-gray-300 hover:text-white transition-colors">&larr; Back to Logs</button>
            <h1 className="text-lg font-bold text-white">Playback: {logIndex.filename || `Log ID ${logId}`}</h1>
          </div>
          <div className="flex items-center gap-4">
              {selectedPids.map((pid, index) => (
                  <select key={index} value={pid} onChange={(e) => handlePidChange(index, e.target.value)} className="bg-gray-700 border border-gray-600 rounded px-2 py-1 text-sm">
                      {availablePids.map(p => <option key={p} value={p}>{p}</option>)}
                  </select>
              ))}
          </div>
        </div>

        {/* Corner Chart */}
        <div className="absolute top-16 right-4 w-[400px] h-[250px] bg-black bg-opacity-60 rounded-lg p-2 z-[1000] backdrop-blur-sm border border-gray-700">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#555" />
                <XAxis dataKey="timestamp" hide={true} />
                <YAxis stroke="#999" domain={['dataMin', 'dataMax']} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#222', border: '1px solid #444' }} 
                  labelStyle={{ color: '#eee' }} 
                />
                <Legend />
                {selectedPids.map((pid, i) => (
                  <Line key={pid} type="monotone" dataKey={pid} stroke={['#8884d8', '#82ca9d', '#ffc658'][i]} strokeWidth={2} dot={false} />
                ))}
              </LineChart>
            </ResponsiveContainer>
        </div>

        {/* Speed & Compass */}
        <div className="absolute top-16 left-4 z-[1000] flex flex-col items-center gap-4">
            <div className="bg-black bg-opacity-60 rounded-lg p-4 text-center w-40 border border-gray-700">
                <div className="text-5xl font-mono font-bold text-yellow-400">{Math.round(currentDataPoint['GPS Speed (MPH)'] || 0)}</div>
                <div className="text-lg text-gray-400">MPH</div>
            </div>
            <div className="bg-black bg-opacity-60 rounded-full p-2 w-24 h-24 flex items-center justify-center border border-gray-700">
                <div style={{ transform: `rotate(${currentBearing}deg)`, transition: 'transform 0.5s linear' }}>
                    <svg width="60" height="60" viewBox="0 0 100 100">
                        <polygon points="50,0 60,20 50,15 40,20" fill="#f87171"/>
                        <polygon points="50,100 60,80 50,85 40,80" fill="#9ca3af"/>
                        <text x="42" y="-2" fill="#f87171" fontSize="20" fontWeight="bold">N</text>
                    </svg>
                </div>
            </div>
        </div>


        {/* Bottom Bar - Gauges & Playback Controls */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-black bg-opacity-50 z-[1000] backdrop-blur-sm">
            {/* Gauges */}
            <div className="flex justify-center items-end gap-4 mb-4 gauge-container">
                <CustomGauge 
                  value={rpm}
                  min={0}
                  max={8000}
                  label="Engine RPM"
                  colors={["#84cc16", "#facc15", "#ef4444"]}
                />
                <CustomGauge 
                  value={mpg}
                  min={0}
                  max={40}
                  label="Instant MPG"
                  colors={["#ef4444", "#facc15", "#84cc16"]}
                />
                <CustomGauge 
                  value={volts}
                  min={10}
                  max={15}
                  label="Volts"
                  colors={["#ef4444", "#84cc16", "#facc15"]}
                />
            </div>

            {/* Scrubber & Controls */}
            <div className="flex items-center justify-center gap-4 max-w-4xl mx-auto">
              <span className="font-mono text-sm">{new Date(currentDataPoint.timestamp * 1000).toLocaleTimeString()}</span>
              <input 
                type="range"
                min="0"
                max={logData.length - 1}
                value={currentIndex}
                onChange={handleScrub}
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
              />
              <span className="font-mono text-sm">{new Date(logData[logData.length - 1].timestamp * 1000).toLocaleTimeString()}</span>
            </div>
            <div className="flex items-center justify-center gap-6 mt-2">
                <div className="flex gap-2">
                    {[0.5, 1, 2, 5].map(speed => (
                        <button key={speed} onClick={() => handleSpeedChange(speed)} className={`px-3 py-1 text-sm rounded ${playbackSpeed === speed ? 'bg-yellow-500 text-black' : 'bg-gray-700 hover:bg-gray-600'}`}>{speed}x</button>
                    ))}
                </div>
                <button onClick={handlePlayPause} className="px-6 py-2 text-lg font-bold bg-yellow-400 text-black rounded-full w-24">
                    {isPlaying ? 'PAUSE' : 'PLAY'}
                </button>
            </div>
        </div>
      </div>
    </>
  );
};

export default LogPlayback;
